import datetime

start = datetime.date(2026,10,5)
holidays = {datetime.date(2026,10,12)}

def add_business_days(current, n, holidays):
    # current is a business day already (day 1 of count); advance n-1 more business days
    count = 1
    while count < n:
        current += datetime.timedelta(days=1)
        if current.weekday() < 5 and current not in holidays:
            count += 1
    return current

def next_business_day(d, holidays):
    d += datetime.timedelta(days=1)
    while d.weekday() >= 5 or d in holidays:
        d += datetime.timedelta(days=1)
    return d

phases = [('Discovery',3), ('Build',6), ('QA',4), ('Release',1)]
cur_start = start
for name, dur in phases:
    end = add_business_days(cur_start, dur, holidays)
    print(name, 'start', cur_start, 'end', end)
    cur_start = next_business_day(end, holidays)
"
